-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261124160000' and name='library_org_folder')=1 then '예' else '아니오' end as value
union all select 'profile parent folder column nullable uuid with set-null fk and index',case when exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_profiles') and attname='org_files_folder' and not attisdropped and atttypid='uuid'::regtype and not attnotnull) and (select count(*) from pg_constraint where conrelid=to_regclass('public.app_profiles') and conname='app_profiles_org_files_folder_fkey' and contype='f' and confdeltype='n')=1 and to_regclass('public.app_profiles_org_files_folder_idx') is not null then '예' else '아니오' end
union all select 'folder organization column nullable uuid with set-null fk and per-workspace unique index',case when exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_library_folders') and attname='organization_id' and not attisdropped and atttypid='uuid'::regtype and not attnotnull) and (select count(*) from pg_constraint where conrelid=to_regclass('public.app_library_folders') and conname='app_library_folders_organization_fkey' and contype='f' and confdeltype='n')=1 and exists(select 1 from pg_index i where i.indexrelid=to_regclass('public.app_library_folders_org_idx') and i.indisunique) then '예' else '아니오' end
union all select 'set org function: definer, empty search_path, no anon or PUBLIC execute',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_library_folder_set_org(uuid,uuid)') and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'') !~ '(^|[{,])=') then '예' else '아니오' end
union all select 'set org function: authenticated only',case when has_function_privilege('authenticated','public.app_library_folder_set_org(uuid,uuid)','execute') and not has_function_privilege('service_role','public.app_library_folder_set_org(uuid,uuid)','execute') then '예' else '아니오' end
union all select 'folders: no organization write privilege for authenticated, none for anon',case when not has_column_privilege('authenticated','public.app_library_folders','organization_id','insert,update') and not has_any_column_privilege('anon','public.app_library_folders','select,insert,update,references') then '예' else '아니오' end
union all select 'folders profiles organizations RLS on and no anon privilege',case when (select count(*) from pg_class where oid in (to_regclass('public.app_library_folders'),to_regclass('public.app_profiles'),to_regclass('public.app_suborganizations')) and relrowsecurity)=3 and not has_any_column_privilege('anon','public.app_library_folders','select,insert,update,references') and not has_any_column_privilege('anon','public.app_profiles','select,insert,update,references') then '예' else '아니오' end
union all select 'profiles table update for authenticated present',case when exists(select 1 from pg_class where oid=to_regclass('public.app_profiles') and relacl::text ~ '(^|[{,])authenticated=[a-zA-Z]*w') then '예' else '아니오' end
union all select 'folders rows',(select count(*)::text from public.app_library_folders)
union all select 'profiles rows',(select count(*)::text from public.app_profiles)
union all select 'folders profiles grants policies triggers hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in (to_regclass('public.app_library_folders'),to_regclass('public.app_profiles'))),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in (to_regclass('public.app_library_folders'),to_regclass('public.app_profiles'))),'')
  ||coalesce((select string_agg(t.tgname::text||':'||t.tgenabled::text||':'||t.tgfoid::regproc::text,',' order by t.tgname) from pg_trigger t where t.tgrelid in (to_regclass('public.app_library_folders'),to_regclass('public.app_profiles')) and not t.tgisinternal),''));
